mapper.insert:
INSERT INTO MES_TQ_SCHEDULE_RESULT ( SCHEDULE_DATE, CX_BATCH_NO, BATCH_NO, ORDER_NO, BEAD_CODE, SAP_MATERIAL_CODE, STEEL_RING_CODE, TRIANGLE_GLUE_CODE, GLUE_CODE, MOUTH_PLATE_CODE, SPEC_SIZE, MACHINE_CODE, UNIT_CONSUME, STOCK_QTY, SUPPLY_TIME, MID_PLAN_QTY, MID_PRODUCE_ORDER, MID_SYS_ANALYSIS, MID_HAND_ANALYSIS, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS, NEXT_MID_PLAN_QTY, NEXT_MID_PRODUCE_ORDER, NEXT_MID_SYS_ANALYSIS, NEXT_MID_HAND_ANALYSIS, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, CX_CLASS6_PLAN, CX_CLASS7_PLAN, CX_CLASS8_PLAN, IS_RELEASE, MARK_CLOSE_OUT_TIP, PRODUCTION_STATUS, REMARK, DATA_VERSION, COMPANY_CODE, FACTORY_CODE ) SELECT * FROM (
SELECT #{item.scheduleDate} AS SCHEDULE_DATE, #{item.cxBatchNo} AS CX_BATCH_NO, #{item.batchNo} AS BATCH_NO, #{item.orderNo} AS ORDER_NO, #{item.beadCode} AS BEAD_CODE, #{item.sapMaterialCode} AS SAP_MATERIAL_CODE, #{item.steelRingCode} AS STEEL_RING_CODE, #{item.triangleGlueCode} AS TRIANGLE_GLUE_CODE, #{item.glueCode} AS GLUE_CODE, #{item.mouthPlateCode} AS MOUTH_PLATE_CODE, #{item.specSize} AS SPEC_SIZE, #{item.machineCode} AS MACHINE_CODE, #{item.unitConsume} AS UNIT_CONSUME, #{item.stockQty} AS STOCK_QTY, #{item.supplyTime} AS SUPPLY_TIME, #{item.midPlanQty} AS MID_PLAN_QTY, #{item.midProduceOrder} AS MID_PRODUCE_ORDER, #{item.midSysAnalysis} AS MID_SYS_ANALYSIS, #{item.midHandAnalysis} AS MID_HAND_ANALYSIS, #{item.nightPlanQty} AS NIGHT_PLAN_QTY, #{item.nightProduceOrder} AS NIGHT_PRODUCE_ORDER, #{item.nightSysAnalysis} AS NIGHT_SYS_ANALYSIS, #{item.nightHandAnalysis} AS NIGHT_HAND_ANALYSIS, #{item.dayPlanQty} AS DAY_PLAN_QTY, #{item.dayProduceOrder} AS DAY_PRODUCE_ORDER, #{item.daySysAnalysis} AS DAY_SYS_ANALYSIS, #{item.dayHandAnalysis} AS DAY_HAND_ANALYSIS, #{item.nextMidPlanQty} AS NEXT_MID_PLAN_QTY, #{item.nextMidProduceOrder} AS NEXT_MID_PRODUCE_ORDER, #{item.nextMidSysAnalysis} AS NEXT_MID_SYS_ANALYSIS, #{item.nextMidHandAnalysis} AS NEXT_MID_HAND_ANALYSIS, #{item.cxClass3Plan} AS CX_CLASS3_PLAN, #{item.cxClass4Plan} AS CX_CLASS4_PLAN, #{item.cxClass5Plan} AS CX_CLASS5_PLAN, #{item.cxClass6Plan} AS CX_CLASS6_PLAN, #{item.cxClass7Plan} AS CX_CLASS7_PLAN, #{item.cxClass8Plan} AS CX_CLASS8_PLAN, '1' AS IS_RELEASE, #{item.markCloseOutTip} AS MARK_CLOSE_OUT_TIP, #{item.productionStatus} AS PRODUCTION_STATUS, #{item.remark} AS REMARK, #{item.dataVersion} AS DATA_VERSION, #{item.companyCode} AS COMPANY_CODE, #{item.factoryCode} AS FACTORY_CODE
) AS t WHERE NOT EXISTS ( SELECT 1 FROM MES_TQ_SCHEDULE_RESULT WHERE SCHEDULE_DATE = t.SCHEDULE_DATE AND MACHINE_CODE = t.MACHINE_CODE AND BEAD_CODE = t.BEAD_CODE )

mapper.delete:
DELETE FROM MES_TQ_SCHEDULE_RESULT
WHERE SCHEDULE_DATE = #{scheduleDate}
AND DATA_VERSION = #{dataVersion}

mapper.select:
SELECT SCHEDULE_DATE, MACHINE_CODE, BEAD_CODE
FROM MES_TQ_SCHEDULE_RESULT
WHERE

    (SCHEDULE_DATE = #{item.scheduleDate}
     AND MACHINE_CODE = #{item.machineCode}
     AND BEAD_CODE = #{item.beadCode})

mapper.delete:
DELETE FROM MES_TQ_SCHEDULE_RESULT WHERE

    (SCHEDULE_DATE = #{item.scheduleDate}
     AND MACHINE_CODE = #{item.machineCode}
     AND BEAD_CODE = #{item.beadCode})
